    def _is_halbarad_hero_card(self, card) -> bool:
        if (getattr(card, "type", "") or "").strip() != '英雄':
            return False
        name = (getattr(card, "name", "") or "").strip()
        if name in self.HALBARAD_HERO_NAMES:
            return True
