    def _has_heir_of_mardil_resource_response(self, card) -> bool:
        """马迪尔的后裔：所附属英雄因卡牌效果获得资源后，可横置以重置该英雄。"""
        if not self._is_heir_of_mardil_attachment(card):
            return False
