    def _is_things_in_the_deep_scenario(self) -> bool:
        series = (self._encounter_series() or "").strip()
        if series in self.THINGS_IN_THE_DEEP_SCENARIO_ALIASES:
            return True
        deck_path = str(getattr(getattr(self, "encounter_drawer", None), "deck_path", "") or "")
